session.targets.implementation:
parser = argparse.ArgumentParser(description='targets')
parser.add_argument('-s', '--set', action='store_true', help='O')
parser.add_argument('-l', '--list', action='store_true', help='O')
parser.add_argument('-t', '--target_properties', action='store_true', help='O')
parser.add_argument('id', nargs='?', help='Target id')
parser.add_argument('-n', '--nocase', action='store_true', help='Case insensitive match in filter')
parsed_args = parser.parse_args(tuple(str(arg) for arg in args))
id = check_int(kwargs.pop("id")) if 'id' in kwargs else None
filter = kwargs.pop("filter", None)
timeout = 3000 if 'timeout' not in kwargs else check_int(kwargs.pop('timeout'))
case_insensitive_match = 1 if parsed_args.nocase is True else 0
if kwargs:
    raise TypeError(f"Invalid args: {list(kwargs.keys())}") from None

if parsed_args.id is not None:
    if id is not None:
        raise Exception("Conflicting args: Specify target id either as positional arg or keyword arg")
    id = int(parsed_args.id)

if self._curchan is None:
    raise Exception("Invalid target. Use 'connect' command to connect to hw_server/TCF agent")

tgts = exec_as_runnable(self._get_targets)
jtag_tgts = {}
if jtag_service.NAME in sorted(protocol.invokeAndWait(self.session._curchan_obj.getRemoteServices)):
    jtag_tgts = exec_as_runnable(self._model.launch_node.jtag_targets)
target_ctx_map = self._model.launch_node.get_target_context_map()
debug_target_properties = self.__get_debug_targets_properties(tgts, jtag_tgts)
if parsed_args.target_properties:
    tp = {}
    if id is None:
        return debug_target_properties
    else:
        tp.update({target_ctx_map[id]: debug_target_properties[target_ctx_map[id]]})
    return tp

if id is not None:
    if id not in target_ctx_map.keys():
        raise Exception(f"No target with id {id}") from None
    node = self._model.get_node(target_ctx_map[id])
    ctx = node.get_run_context_data().getID()

    for t in self._targets:
        if ctx == t.ctx:
            self._curtarget = t
            self._current_node = node
            t._node = node
            return t
    t = xsdb.target.Target(self._curchan, id, node, xsdb.debug_session)
    self._targets.append(t)
    self._curtarget = t
    self._current_node = node
    return t

# Filter based on properties
if filter is not None:
    ctx = None
    new_targets = []
    new_tgts = {}
    # TODO - proper handling
    # temp hack to add () if () are not present at the front and end of the filter string
    if filter[0] != '(':
        filter = '(' + filter + ')'
    if filter.count('(') != filter.count(')'):
        raise Exception('Braces missing in the filter option.') from None
    filter_stack_list = self.__filter_parser(filter)
    filter_stack = []
    for stk in filter_stack_list:
        if isinstance(stk, list):
            filter_stack = stk
    start_time = round(time.time() * 1000)
    delta = 0
    while delta < timeout:
        for ctx_id, tgt in tgts.items():
            if ctx_id == '':
                continue
            props = debug_target_properties[ctx_id]
            if self.__parse_filter_string(filter_stack, props, 0, case_insensitive_match):
                id = tgt['target_id']
                ctx = tgt['id']
                name = tgt['run_context']['Name']
                new_targets.append(name)
                new_tgts.update({ctx: tgt})
        if len(new_targets):
            break
        tgts = exec_as_runnable(self._get_targets)
        target_ctx_map = self._model.launch_node.get_target_context_map()
        delta = round(time.time() * 1000) - start_time

    if parsed_args.set:
        if id is None or ctx is None:
            raise Exception(f"No target with filter '{filter}'") from None
        if len(new_targets) > 1:
            raise Exception(f"More than one targets with filter '{filter}':", new_targets) from None
        node = self._model.get_node(target_ctx_map[id])
        for t in self._targets:
            if ctx == t.ctx:
                self._curtarget = t
                self._current_node = node
                return t

        t = xsdb.target.Target(self._curchan, id, node, xsdb.debug_session)
        self._targets.append(t)
        self._curtarget = t
        self._current_node = node
        return t
    else:
        tgts = new_tgts

result = self.__print_targets(tgts)
if parsed_args.list == 0:
    print(result)
else:
    return result.split('\n')

session.connect.implementation:
parser = argparse.ArgumentParser(description='connect')
parser.add_argument('-n', '--new', action='store_true',
                    help='create new connection even if one exist to the same url')
parser.add_argument('-l', '--list', action='store_true', help='list connections')
parser.add_argument('-r', '--redirect', action='store_true', help='redirect connection')
parser.add_argument('-s', '--symbols', action='store_true', help='enable symbol level debug')
parser.add_argument('host', nargs='?', help='Host name')
parser.add_argument('port', nargs='?', help='Port number')

parsed_args = parser.parse_args(tuple(str(arg) for arg in args))

if parsed_args.host is not None:
    host = parsed_args.host
if parsed_args.port is not None:
    port = parsed_args.port
port = check_int(port)

if parsed_args.list is True:
    output = list()
    for channel_name, objects in self.__channel_map.items():
        channel_obj = objects[0]
        remote_peer = channel_obj.remote_peer
        cn_path = self.__get_connection_path(remote_peer)
        name = ''
        i = 1
        for cn in cn_path:
            name += cn
            if i < len(cn_path):
                name += ' -> '
                i += 1
        if channel_name == self._curchan:
            active = '*'
        else:
            active = ' '
        output.append("{0:3s}{1}{2}{3:2s}{4}{5}".format('', active, channel_name, '', name, '\r\n'))
    print(output)
    return output

set_chan = kwargs.pop("set", None)
if set_chan is not None:
    if set_chan in self.__channel_map.keys():
        self._curchan_obj = self.__channel_map[set_chan][0]
        self._model = self.__channel_map[set_chan][1]
        self._curchan = set_chan
    else:
        raise Exception(f'Channel {set_chan} is not available') from None
    return

url = kwargs.pop("url", None)
xvc_url = kwargs.pop("xvc_url", None)
path = kwargs.pop("path", None)
if kwargs:
    raise TypeError(f"Invalid args: {list(kwargs.keys())}") from None
if url is None:
    url = f'TCP:{host}:{port}'
else:
    # TCF doesn't accept lower case "tcp", so replace "tcp" with "TCP"
    url = url.replace("tcp", "TCP")

if parsed_args.symbols is True:
    # Use symbol server for remote connections
    props = self.__launch_server('symbol_server', 'tcp:127.0.0.1:0')
    if "Port" in props.keys():
        sym_url = "TCP:127.0.0.1:" + str(props.get("Port"))
        if path is None:
            path = [sym_url, url]
        else:
            path.insert(0, sym_url)
    else:
        print("WARNING: Unable to launch symbol server")

if path is not None:
    if len(path) == 0:
        raise Exception('invalid path argument, must be non-empty list of URLs') from None
    if parsed_args.new is False:
        connections = list()
        for channel_name, objects in self.__channel_map.items():
            peer = objects[0].remote_peer.attrs
            url_name = peer.get('TransportName') + ":" + peer.get('Host') + ":" + peer.get('Port')
            connections.append((channel_name, url_name))
        for cn in connections:
            chnl = cn[0]
            url = cn[0]
            if url == path:
                self._curchan = chnl
                self._curtarget = None
                self._current_node = None
                self._model = self.__channel_map[chnl][1]
                return self._curchan
    chan = self.connect('-n', url=path[0])
    for url_p in path[1:]:
        self.connect('-n', '-r', url=url_p)
    return self._curchan

if parsed_args.redirect is True:
    tcp_chan = self.__channel_map.get(self._curchan, None)[0]
    if tcp_chan is not None:
        exec_in_dispatch_thread(tcp_chan.redirect, self._parse_url_params(url))
        return self._curchan

if parsed_args.new is False:
    for channel_name, objects in self.__channel_map.items():
        peer = objects[0].remote_peer.attrs
        name = peer.get('TransportName') + ":" + peer.get('Host') + ":" + peer.get('Port')
        if url == name:
            self._curchan = channel_name
            self._curtarget = None
            self._current_node = None
            self._model = objects[1]
            return self._curchan
try:
    chan = tcf.connect(url)
    if chan is not None:
        self._curchan_obj = chan
        self._model = TcfModel(chan, self.session)
        self._curchan = "tcfchan#" + str(self.__channel_id)
        self._curtarget = None
        self._current_node = None
        self.__channel_map[self._curchan] = [chan, self._model]
        self.__channel_id = self.__channel_id + 1
        if trace_listener == 1:
            protocol.invokeAndWait(chan.addTraceListener, TraceListener())
        protocol.invokeAndWait(self._model.on_connected)
        services_list = sorted(protocol.invokeAndWait(self.session._curchan_obj.getRemoteServices))
        if 'Memory' in services_list and "RunControl" in services_list:
            exec_as_runnable(self._get_targets)
        print(self._curchan)
    else:
        raise Exception(f"Could not connect to the server") from None

except Exception as e:
    if url != "TCP:127.0.0.1:0" and url != "TCP:127.0.0.1:3121":
        raise Exception(e)
    else:
        props = self.__launch_server(server, url)
        if url == "TCP:127.0.0.1:0":
            if "Port" in props.keys():
                url = "TCP:127.0.0.1:" + str(props.get("Port"))
            else:
                raise Exception(f"Unable to get port number of {server}") from None
        self.connect(url=url)

if xvc_url is not None:
    fields = xvc_url.split(':')
    if len(fields) > 3:
        raise Exception(f'invalid xvc url, expected format tcp:host:port, got {xvc_url}') from None
    if fields[0].lower() == 'tcp':
        host = fields[1]
        port = fields[2]
        if host == '':
            host = '127.0.0.1'
        if port == '':
            port = '10200'
        arguments = {'host': host, 'port': port}
        tcf_jtag = TcfJtag(self.session)
        exec_in_dispatch_thread(tcf_jtag.jtagcable_open_server, 'xilinx-xvc', arguments)

return self._curchan

_breakpoint.add.implementation:
if self._id is not None:
    raise Exception("Breakpoint is already added.") from None

parser = argparse.ArgumentParser(description='bpadd')
parser.add_argument('-t', '--temp', action='store_true', help='trigger breakpoint once')
parser.add_argument('-sk', '--skip_prologue', action='store_true', help='skip function prologue')
parser.add_argument('arg1', nargs='?', help='Address or File:Line of a breakpoint')
parsed_args = parser.parse_args(tuple(str(arg) for arg in args))

if len(args) != 0:
    if parsed_args.arg1 is not None and ('addr' in kwargs or 'file' in kwargs or 'line' in kwargs):
        raise Exception(f"Unexpected arguments: {args}") from None

address = None
file = None
line = None

if parsed_args.arg1 is not None:
    arg = parsed_args.arg1.split(':')
    if len(arg) == 1:
        address = arg[0]
    elif len(arg) == 2:
        file = arg[0]
        line = int(arg[1])
    else:
        raise Exception(f"Unexpected arguments: {args}") from None

bp = {breakpoints.PROP_ID: str(uuid.uuid4()), breakpoints.PROP_ENABLED: True, breakpoints.PROP_TEMPORARY: False,
      breakpoints.PROP_SKIP_PROLOGUE: False}

if parsed_args.temp:
    bp[breakpoints.PROP_TEMPORARY] = True

if parsed_args.skip_prologue:
    bp[breakpoints.PROP_SKIP_PROLOGUE] = True

if 'addr' in kwargs:
    address = str(kwargs.pop("addr"))
if address is not None:
    bp[breakpoints.PROP_LOCATION] = address
    self._location = bp[breakpoints.PROP_LOCATION]

if 'file' in kwargs:
    file = kwargs.pop("file")
if file is not None:
    bp[breakpoints.PROP_FILE] = file

if 'line' in kwargs:
    line = kwargs.pop("line")
    if not isinstance(line, int):
        raise Exception('\'line\' must be integer.') from None
if line is not None:
    bp[breakpoints.PROP_LINE] = line

if 'type' in kwargs:
    bptype = kwargs.pop("type")
    if bptype not in self.__bp_types:
        raise Exception(f"Unknown breakpoint type \'{bptype}\' : must be "
                        f"{', '.join(list(self.__bp_types.keys()))}") from None
    else:
        bp[breakpoints.PROP_TYPE] = self.__bp_types[bptype]

if 'mode' in kwargs:
    mode = check_int(kwargs.pop("mode"))
    if not isinstance(mode, int):
        raise Exception(f'Invalid mode \'{mode}\'. Must be integer from 0x0 to 0xf.') from None
    bp[breakpoints.PROP_ACCESS_MODE] = mode & 0x0f

ct_input_list = []
if 'ct_input' in kwargs:
    ct_input = kwargs.pop("ct_input")
    if isinstance(ct_input, list):
        for c in ct_input:
            if is_int(c) is False:
                raise Exception('\'ct_input\' must be list of integers. Refer help for details.') from None
        ct_input_list = ct_input.copy()
    elif isinstance(ct_input, int):
        ct_input_list.append(ct_input)
    else:
        raise Exception('\'ct_input\' must be list of integers or integer. Refer help for details.') from None
    bp[breakpoints.PROP_CT_INP] = ct_input_list
    self._ct_input = bp[breakpoints.PROP_CT_INP]

ct_output_list = []
if 'ct_output' in kwargs:
    ct_output = kwargs.pop("ct_output")
    if isinstance(ct_output, list):
        for c in ct_output:
            if is_int(c) is False:
                raise Exception('\'ct_output\' must be list of integers. Refer help for details.') from None
        ct_output_list = ct_output.copy()
    elif isinstance(ct_output, int):
        ct_output_list.append(ct_output)
    else:
        raise Exception('\'ct_output\' must be list of integers or integer. Refer help for details.') from None
    bp[breakpoints.PROP_CT_OUT] = ct_output_list
    self._ct_output = bp[breakpoints.PROP_CT_OUT]

if 'skip_on_step' in kwargs:
    skip_on_step = kwargs.pop("skip_on_step")
    if is_int(skip_on_step) is False:
        raise Exception('\'skip_on_step\' must be integer from 0 to 2.') from None
    if skip_on_step != 0:
        if skip_on_step > 2:
            raise Exception(f'Unknown skip_on_step \'{skip_on_step}\' : should be 0, 1 or 2.') from None
        if len(ct_input_list) != 0:
            bp[breakpoints.PROP_SKIP_ON_STEP] = skip_on_step
        else:
            raise Exception('\'skip_on_step\' is valid only for cross trigger input breakpoints.') from None

if 'enable' in kwargs and kwargs.pop("enable") == 0:
    bp[breakpoints.PROP_ENABLED] = False

if 'condition' in kwargs:
    condition = kwargs.pop("condition")
    if isinstance(condition, str):
        bp[breakpoints.PROP_CONDITION] = condition
    else:
        raise Exception('\'condition\' must be string.') from None

if 'ignore_count' in kwargs:
    ignore_count = kwargs.pop("ignore_count")
    if isinstance(ignore_count, int):
        bp[breakpoints.PROP_IGNORE_COUNT] = ignore_count
    else:
        raise Exception('\'ignore_count\' must be integer.') from None

if 'target_id' in kwargs:
    tgt_ctx = []
    ctx = kwargs.pop("target_id")
    if ctx != 'all':
        tgt_ctx.append(ctx)
        bp[breakpoints.PROP_CONTEXT_IDS] = tgt_ctx

if 'action' in kwargs:
    self._action = kwargs.pop("action")
    if 'action_args' in kwargs:
        self._action_args = kwargs.pop("action_args")

if kwargs:
    raise TypeError(f"Invalid args: {list(kwargs.keys())}") from None

self._id = bp[breakpoints.PROP_ID]
self._enabled = bp[breakpoints.PROP_ENABLED]
self._show_status = True
s = self._session
s._bptable[s._bpid] = self
s._bpid = s._bpid + 1
exec_in_dispatch_thread(self.__bp_add, bp)
return s._bpid - 1

_breakpoint.remove.implementation:
if self._id is None:
    raise Exception("Breakpoint is already removed.") from None

exec_in_dispatch_thread(self.__bp_remove, [self._id])
for bpid, bp in self._session._bptable.items():
    if bp._id == self._id:
        del self._session._bptable[bpid]
        break
